//! Hybrid Reverb's IR display: the shaped response's envelope, the current selection, arrows that
//! step through the responses and on into the next category, and a note that the responses are
//! generated by code.

use super::{PanelCtx, PanelDef};
use crate::ui::theme::{self, *};
use egui::{Align2, CornerRadius, Pos2, Rect, Sense, Stroke, Vec2};
use rlive_core::ParamId;
use rlive_devices::devices::b7::{hybrid_ir, hybrid_reverb as hr};

pub const PANEL: PanelDef = PanelDef {
    name: "hybrid_ir_view",
    size: Vec2::new(280.0, 90.0),
    views: hr::IR_VIEW_LEN,
    draw,
};

/// How the arrows step through a category, moving on to the next one at the ends, per the manual.
fn step(category: usize, index: usize, forward: bool) -> (usize, usize) {
    let last_index = hybrid_ir::PER_CATEGORY - 1;
    if forward {
        if index < last_index {
            (category, index + 1)
        } else {
            ((category + 1) % hybrid_ir::CATEGORIES.len(), 0)
        }
    } else if index > 0 {
        (category, index - 1)
    } else {
        (
            (category + hybrid_ir::CATEGORIES.len() - 1) % hybrid_ir::CATEGORIES.len(),
            last_index,
        )
    }
}

fn draw(ui: &mut egui::Ui, panel: &mut PanelCtx) {
    let rect = ui.max_rect();
    let mut view = [0.0f32; hr::IR_VIEW_LEN];
    let live = panel.view.is_some_and(|v| v.read(hr::IR_VIEW, &mut view));

    let category = panel.value(ParamId(hr::IR_CATEGORY)).unwrap_or(0.0).round() as usize;
    let index = panel.value(ParamId(hr::IR_SELECT)).unwrap_or(0.0).round() as usize;
    let selection = if category == hybrid_ir::USER_CATEGORY {
        "User: drop a file on the slot below".to_string()
    } else {
        let name = hr::ir_names(category).get(index).copied().unwrap_or("");
        format!(
            "{}: {name}",
            hybrid_ir::CATEGORIES.get(category).copied().unwrap_or("")
        )
    };

    let wave = Rect::from_min_max(
        rect.min + Vec2::new(0.0, 16.0),
        rect.max - Vec2::new(0.0, 14.0),
    );
    let p = ui.painter();
    p.rect_filled(wave, CornerRadius::same(2), pal().knob_track);
    if live {
        let dx = wave.width() / (hr::IR_VIEW_LEN - 2) as f32;
        for (i, v) in view[1..].iter().enumerate() {
            let x = wave.left() + i as f32 * dx;
            let h = v.clamp(0.0, 1.0) * wave.height() * 0.5;
            p.line_segment(
                [
                    Pos2::new(x, wave.center().y - h),
                    Pos2::new(x, wave.center().y + h),
                ],
                Stroke::new(1.0, pal().accent),
            );
        }
    }
    p.text(
        rect.left_top(),
        Align2::LEFT_TOP,
        selection,
        theme::font(10.0),
        pal().text,
    );
    p.text(
        rect.left_bottom(),
        Align2::LEFT_BOTTOM,
        "Impulse responses are generated by code, not recorded.",
        theme::font(9.0),
        pal().text_dim,
    );

    let arrows = [
        ("\u{25C0}", false, rect.right() - 34.0),
        ("\u{25B6}", true, rect.right() - 16.0),
    ];
    for (label, forward, x) in arrows {
        let at = Rect::from_center_size(Pos2::new(x, rect.top() + 7.0), Vec2::new(16.0, 14.0));
        let response = ui.interact(
            at,
            ui.scope_id().with(("ir_arrow", panel.device.id, forward)),
            Sense::click(),
        );
        ui.painter().text(
            at.center(),
            Align2::CENTER_CENTER,
            label,
            theme::font(10.0),
            pal().text,
        );
        if response.clicked() {
            let (next_category, next_index) = step(category, index, forward);
            panel.set(ParamId(hr::IR_CATEGORY), next_category as f64);
            panel.set(ParamId(hr::IR_SELECT), next_index as f64);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_arrows_run_on_into_the_next_category() {
        assert_eq!(step(0, 0, true), (0, 1));
        assert_eq!(step(0, hybrid_ir::PER_CATEGORY - 1, true), (1, 0));
        assert_eq!(step(1, 0, false), (0, hybrid_ir::PER_CATEGORY - 1));
        assert_eq!(
            step(0, 0, false),
            (hybrid_ir::CATEGORIES.len() - 1, hybrid_ir::PER_CATEGORY - 1)
        );
    }
}
